import { Component } from '@angular/core';

@Component({
  selector: 'app-ejercicio19',
  templateUrl: './ejercicio19.component.html',
  styleUrls: ['./ejercicio19.component.css']
})
export class Ejercicio19Component {

  productName: string = '';
  userEmail: string = '';

}
<!-- ejercicio19.component.html -->
<input [(ngModel)]="productName" placeholder="Enter product name">
<button (click)="sendProductName()">Search</button>

<!-- Asumiendo que pasas el nombre del producto y el email directamente al componente hijo -->
<app-componente-hijo [productName]="productName" [userEmail]="userEmail"></app-componente-hijo>
